def last_line(text: str | None, pred) -> str | None:
    hit = None
    for ln in (text.splitlines() if text else []):
        if pred(ln):
            hit = ln
    return hit

edits.new:
def last_line(text: str | None, pred) -> str | None:
    for ln in (text.splitlines() if text else []):
        if pred(ln):
            return ln
    return None
